// Generated by Skyramp — UI test for the field-reorder save confirmation.
//
// Scenario: field-reorder-failed-save-shows-false-success  (category: bug_caught)
//
// setSort() in fields-management.vue calls notify({ title: t('field_order_saved'),
// type: 'success' }) unconditionally after `await fieldsStore.updateFields(...)`.
// updateFields (app/src/stores/fields.ts) swallows API errors — it rolls local state
// back and calls unexpectedError(error) without rethrowing — so the awaited promise
// always resolves and the success toast fires even when the save was rejected.
//
// This test drives a reorder whose PATCH /fields/{collection} is rejected with 403 and
// asserts the user is NOT told the order was saved. It FAILS on the current code, which
// is the intended outcome: it documents the false-success bug. It will pass once
// updateFields propagates the failure and setSort gates the notify on success.
import { test } from '@skyramp/skyramp';
import { expect } from '@playwright/test';
import {
	login,
	createCollection,
	dragField,
	fieldOrder,
	deleteCollectionInOtherTab,
} from './skyramp_field_reorder_helpers';

const baseUrl = process.env.SKYRAMP_TEST_BASE_URL || 'http://localhost:8055';

test('rejected field reorder does not report success', async ({ page }) => {
	test.setTimeout(180000);
	page.setDefaultTimeout(15000);

	await login(page, baseUrl);
	const collection = await createCollection(page, baseUrl, 'qa_reorder_fail');

	expect(await fieldOrder(page)).toEqual(['id', 'status', 'date_created']);

	// Another admin deletes the collection; this tab is now stale.
	await deleteCollectionInOtherTab(page, baseUrl, collection);

	// Arm both watchers BEFORE the drag. The success toast auto-dismisses after ~3s, so
	// checking for it only after the request settles would race its lifetime and pass
	// spuriously. Polling from before the action catches it whenever it renders.
	const rejected = page.waitForResponse(
		(r) => r.url().includes(`/fields/${collection}`) && r.request().method() === 'PATCH',
	);
	const successToastAppeared = page
		.getByText('Field order saved')
		.waitFor({ state: 'visible', timeout: 10000 })
		.then(() => true)
		.catch(() => false);

	await dragField(page, 1, 0);

	// The reorder really was rejected by the API.
	const response = await rejected;
	expect(response.status()).toBe(403);

	const errorBody = await response.json();
	expect(errorBody.errors[0].extensions.code).toBe('FORBIDDEN');
	expect(errorBody.errors[0].message).toBe(
		`You don't have permission to access collection "${collection}" or it does not exist. Queried in root.`,
	);
	expect(errorBody.errors[1]).toBeUndefined();

	// The failure is surfaced to the user.
	await expect(page.getByText('Forbidden', { exact: false }).first()).toBeVisible();

	// The optimistic reorder is rolled back, so the original order is restored...
	expect(await fieldOrder(page)).toEqual(['id', 'status', 'date_created']);

	// ...and the app must NOT also claim the order was saved.
	// FAILS today: setSort notifies success because updateFields never rethrows.
	expect(await successToastAppeared).toBe(false);
});
